      SUBROUTINE DFOL2CC     DERIVATIVE OF SECOND-ORDER TRANSFER MATRIX ELEMENTS WITH C     RESPECT TO MAGNET LENGTHCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'CC     LOCAL VARIABLESC      REAL  BLOB, DCS, DCSP, DSNCC---------------------------------------------------      J = JQUAD      CS = R(J,J)      SN = R(J,J+1)      DCS = - KQ2*SN*LVE      DSN = CS*LVE      DCSP = - KQ2*CS*LVE      BLOB = 0.5*(KQ2*SN + KQ2*L*CS)*LVC      TV(J,J+15) = BLOB      TV(J+1,J+16) = BLOB      TV(J,J+16) = 0.5*(DSN - LV*CS - L*DCS)      TV(J+1,J+15) = 0.5*KQ2*(2.0*CS - KQ2*L*SN)*LVC      TV(5,J*(J+1)/2) = - 0.25*(KQ2*LV + DCSP*CS - KQ2*SN*DCS)      TV(5,J*(J+3)/2) = - 0.5*(- KQ2*DSN*SN + SN*DCSP)      TV(5,J*(J+3)/2+1) = - 0.25*(LV + DCS*SN + CS*DSN)  100 RETURN      END